mapper.select:
SELECT p.photo_id AS photoId, p.img_url AS imageUrl, p.created_at AS createdAt, a.heart AS heart, a.editable AS editable, p.user_list AS partnerEmails FROM photo p JOIN archive a ON p.photo_id = a.photo_id WHERE a.user_id = #{userId} AND a.deleted_at IS NULL
AND DATE(a.created_at) >= #{cond.startDate}
AND DATE(a.created_at) <= #{cond.endDate}
AND a.heart = 1
AND a.heart = 0
p.user_list LIKE CONCAT('%"', #{email}, '"%')
AND p.photo_id < #{cond.cursor}
ORDER BY p.photo_id DESC LIMIT #{cond.limit}
